grep -F V3_BASELINE_CONSUMER_AUDIT_PASSED "$out/V3BaselineConsumerAudit.log"
grep -F CSS_EXISTENCE_AUDIT_PASSED "$out/CSSExistenceAudit.log"
grep -F FAULT_SHARPNESS_AUDIT_PASSED "$out/FaultSharpnessAudit.log"
grep -F Q37_GATES_AUDIT_PASSED "$out/Q37GatesAudit.log"
grep -F CONSTRUCTIVE_SYNTHESIS_AUDIT_PASSED "$out/ConstructiveSynthesisAudit.log"
